custom.rulesPlaceholder:
(month, dayOfMonth, dayName, hour, minute, url, helpers) => {
  const yt = helpers.getPlatformHelper().youtube();

  // Hide the Shorts nav button entirely on YouTube.
  yt.hideShortButton();

  // Hide Shorts whose author handle is longer than 16 characters,
  // and exit the page if the user opens such a Short directly.
  yt.hideShorts((item) => item.author && item.author.length > 16, {
    blockPageOnVisit: true
  });

  // 30 minute backward timer that ticks only on /shorts/* pages.
  const tid = yt.setShortsTimer({
    id: "yt-shorts",
    direction: "backward",
    currentMs: 30 * 60 * 1000,
    displayName: "YT Shorts"
  });

  return helpers.getTimerHelper().isExpired(tid) ? -1 : 0;
}

